    .btn-primary {
      background: var(--color-coral);
      color: #fff;
    }

    .btn-secondary {
      background: var(--color-sage);
      color: #fff;
    }

    .fact-box {
      background: var(--color-cream);
      border-left: 5px solid var(--color-coral);
      border-radius: 12px;
