      <div class="gallery" aria-label="Photo gallery of Pobrecita">
        <div class="photo" title="Nap time">😴</div>
        <div class="photo" title="Treat time">🦴</div>
        <div class="photo" title="Bath time">🛁</div>
        <div class="photo" title="Zoomies">🏃</div>
      </div>
    </section>

    <section id="fun">
      <h2>🧠 Fun Facts</h2>
      <div class="fact-box" id="fact-box" aria-live="polite">
        Pobrecita can hear a cheese wrapper from three rooms away.
      </div>
      <div class="action-bar">
        <button class="btn-secondary" onclick="newFact()">🔄 New Fact</button>
      </div>
    </section>

    <section id="contact">
      <h2>📬 Contact Pobrecita</h2>
      <p>
        Want to send fan mail, schedule a playdate, or donate treats?
        Reach out via carrier pigeon or the button below.
      </p>
      <div class="action-bar">
        <a href="mailto:pobrecita@example.com?subject=Hello%20Pobrecita!" class="btn-primary" style="border-radius:999px; padding:0.85rem 1.6rem; display:inline-flex; align-items:center; gap:0.5rem;">
          ✉️ Send Email
        </a>
      </div>
    </section>
  </main>

  <footer>
    <p>Made with <span class="heart">♥</span> for Pobrecita · All barks reserved.</p>
  </footer>

  <script>
    let treats = 0;

    function giveTreat() {
      treats++;
      document.getElementById('treat-counter').textContent = `Treats received: ${treats}`;
      if (treats === 1) {
        alert('Pobrecita says thank you with a very polite tail wag! 🐾');
      } else if (treats === 5) {
        alert('She’s doing a happy dance! 💃🐕');
      } else if (treats === 10) {
        alert('BEST. HUMAN. EVER. 🏆');
      }
    }

    function bark() {
      const utterance = new SpeechSynthesisUtterance('Woof woof!');
      utterance.pitch = 1.2;
      utterance.rate = 1.1;
      window.speechSynthesis.speak(utterance);
    }

    const facts = [
      'Pobrecita can hear a cheese wrapper from three rooms away.',
      'Her favorite toy is a stuffed squirrel she has “loved” bald.',
      'She firmly believes every lap is her personal bed.',
      'Pobrecita’s tail wags in perfect circles when excited.',
      'She once stole an entire slice of pizza and felt zero regret.',
      'Her hidden talent: opening doors with her nose.',
      'Pobrecita understands three languages: English, Spanish, and Snack.',
      'She has never met a puddle she didn’t want to jump in.'
    ];

    function newFact() {
      const box = document.getElementById('fact-box');
      let next = facts[Math.floor(Math.random() * facts.length)];
      while (next === box.textContent) {
        next = facts[Math.floor(Math.random() * facts.length)];
      }
      box.textContent = next;
    }
  </script>
